
(()=>{
const query = new URLSearchParams(location.search);
const referenceScenes = {"today-new": {"screen": "today", "seen": {}}, "today-partial": {"screen": "today", "seen": {"dairy": 1}}, "today-reviewed": {"screen": "today", "seen": {"dairy": 1, "bowel": 1, "sleep": 1, "energy": 2}}, "goal-unread": {"screen": "goal", "selected": "symptoms", "seen": {}, "history": [{"screen": "today", "selected": "symptoms", "finding": "dairy"}]}, "goal-partial": {"screen": "goal", "selected": "symptoms", "seen": {"dairy": 1}, "history": [{"screen": "today", "selected": "symptoms", "finding": "dairy"}]}, "unread-list": {"screen": "unread", "seen": {}, "history": [{"screen": "today", "selected": "symptoms", "finding": "dairy"}]}, "updated-finding": {"screen": "detail", "selected": "energy", "finding": "energy", "seen": {"energy": 2}, "history": [{"screen": "today", "selected": "energy", "finding": "energy"}]}};
const scene = referenceScenes[query.get('scene')] ? query.get('scene') : 'today-new';
const theme = query.get('theme') === 'dark' ? 'dark' : 'light';
const phone = document.querySelector('.pt-phone');
phone.dataset.theme = theme;
phone.setAttribute('aria-label','Plectara Today Insights reference, '+theme+' theme');
document.getElementById('plectara-today-insights-nov5').style.zoom = query.get('scale')==='1' ? 1 : 3;
document.documentElement.dataset.scene = scene;
document.documentElement.dataset.theme = theme;

const root=document.getElementById('plectara-today-insights-nov5');
const logo='data:image/svg+xml;base64,';
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const native=(code)=>`<span class="pt-material" aria-hidden="true">&#${code};</span>`;
const goalIcon=g=>g.icon==='stomach'?'<span class="pt-stomach" aria-hidden="true"></span>':icon(g.icon);
const goals=[
 {id:'symptoms',name:'Reduce Symptoms',icon:'trending-down',findings:['dairy','bowel']},
 {id:'digestion',name:'Improved Digestion',icon:'stomach',findings:['dairy','bowel']},
 {id:'sleep',name:'Improved Sleep',icon:'bed-double',findings:['sleep']},
 {id:'activity',name:'Be More Active',icon:'footprints',findings:['bowel']},
 {id:'pressure',name:'Improve Blood Pressure',icon:'heart-pulse',findings:[],status:'no-pattern',preview:'No clear pattern yet',heading:'No clear pattern yet',body:'Your blood pressure and habit records have been reviewed. No clear connection stood out in this review period.',context:'This does not mean your habits have no effect on your blood pressure. It means a clear pattern has not emerged from these records.'},
 {id:'treatment',name:'See If a Treatment Is Working',icon:'clipboard-check',findings:[],status:'needs-input',preview:'Add symptom logs',heading:'Add symptom logs',body:'Your treatment records are available, but this review period has no symptom logs to compare with them.',context:'Record symptoms when they occur, including how they feel. Those details help put your treatment records in context.'},
 {id:'energy',name:'More Energy',icon:'zap',findings:['energy']},
 {id:'stress',name:'Less Stress',icon:'wind',findings:[],status:'gathering',preview:'Gathering context',heading:'Gathering context',body:'There is not enough relevant information to assess patterns for this goal yet.',context:'Less Stress remains part of your Insights overview. A finding will appear here if a supported connection emerges.'}
];
const findings={
 dairy:{revision:1,change:'New',preview:'Possible dairy–bloating link',title:'Dairy meals and bloating',status:'Developing Pattern',body:'Bloating was logged near dairy-tagged meals. This is a possible connection to explore.',detail:'The current meal analysis matches symptoms within four hours before or after a meal. That timing does not establish which came first or show that dairy caused the symptom.',foot:'Related goals: Reduce Symptoms and Improved Digestion.'},
 sleep:{revision:1,change:'New',preview:'Less activity after poor sleep',title:'Less activity after poor sleep',status:'Developing Pattern',body:'Your records show less activity after nights marked as short or poor sleep.',detail:'This finding is based on your sleep and activity records. A missing activity entry is not proof of an inactive day, and the relationship does not establish cause.',foot:'Related goal: Improved Sleep.'},
 bowel:{revision:1,change:'New',preview:'Possible activity–bowel link',title:'Activity and bowel changes',status:'Possible Connection',body:'Intense activity and unusual bowel movements appeared near each other in your records.',detail:'The timing of these records suggests a possible connection. Other habits or unrecorded activity could also contribute.',foot:'Related goals: Reduce Symptoms, Improved Digestion, and Be More Active.'},
 energy:{revision:2,change:'Updated',preview:'Higher energy on active days',title:'Higher energy on active days',status:'Developing Pattern',body:'Your energy ratings were higher on days with activity recorded.',changed:'Earlier records were mixed. Recent records show a more consistent relationship between recorded activity and higher energy ratings.',detail:'This finding compares energy ratings on days with and without an activity log. Missing activity logs do not establish inactivity.',foot:'Energy findings stay on this device.'}
};
const screens=['today','all','unread','goal','status','detail'];
const states=new Map();
function savedViews(data){const s=data?.modelContent||data;return s?.version===2?s.views||{}:{};}
const saved={reference:referenceScenes[scene]};
function isUnread(st,id){return (st.seen[id]||0)<findings[id].revision;}
function activeGoals(st){return st.profile==='Eight Selected Goals'?goals:goals.filter(g=>['symptoms','digestion','sleep','energy'].includes(g.id));}
function unreadFor(st,g){return g.findings.filter(id=>isUnread(st,id));}
function uniqueFindings(st){return [...new Set(activeGoals(st).flatMap(g=>g.findings))];}
function changedIds(st){return uniqueFindings(st).filter(id=>isUnread(st,id));}
function rowState(st,g){const unread=unreadFor(st,g);const id=unread[0]||g.findings[0];return {unread,id,badge:unread.length>1?`${unread.length} Unread`:unread.length?findings[id].change:'',preview:id?findings[id].preview:g.preview};}
function persist(){}
function rows(st){return activeGoals(st).map(g=>{const r=rowState(st,g);return `<button type="button" class="pt-goal cursor-interaction" data-goal="${g.id}" data-unread="${r.unread.length>0}" data-gathering="${g.status==='gathering'}" data-status="${g.status||'finding'}" aria-label="${g.name}. ${r.unread.length?r.badge+'. ':''}${r.preview}. ${g.findings.length>1?'Open goal findings':g.findings.length?'Open finding':'Open goal status'}."><span class="pt-goal-icon">${goalIcon(g)}</span><span><span class="pt-goal-heading"><span class="pt-goal-name">${g.name}</span>${r.badge?`<span class="pt-finding-state">${r.badge}</span>`:''}</span><span class="pt-preview">${r.preview}</span></span>${icon('chevron-right','pt-chevron')}</button>`;}).join('');}
function overview(st){const count=changedIds(st).length;return `<section class="pt-card" aria-label="Insights for your selected goals"><header class="pt-insights-head"><div class="pt-title">${native(58183)}<h2>Insights</h2></div>${count?`<button type="button" data-action="unread" class="pt-update-count cursor-interaction" aria-label="${count} unread findings. Review new and updated insights.">${icon('mail')}${count} Unread</button>`:'<span class="pt-reviewed-count">All reviewed</span>'}</header><div class="pt-goals">${rows(st)}</div><button type="button" class="pt-explore cursor-interaction" data-action="all">Explore Insights${icon('arrow-right')}</button></section><section class="pt-card pt-below" aria-label="Existing plan context"><h3>${icon('clipboard-list')}Your Plan</h3><p>Two-Week Activity Check</p><small>Day 6 of 14</small></section><section class="pt-card pt-below"><h3>${icon('notebook-pen')}Today’s Logs</h3><p>Activity · Walking</p><small>12:15 PM</small></section>`;}
function backLabel(st){const last=st.history.at(-1);if(!last||last.screen==='today')return 'Today';if(last.screen==='all')return 'Your Goals';if(last.screen==='unread')return 'Unread Insights';if(last.screen==='goal')return goals.find(g=>g.id===last.selected)?.name||'Goal Findings';return 'Insights';}
function backButton(st){return `<button type="button" class="pt-back cursor-interaction" data-action="back">${icon('arrow-left')}${backLabel(st)}</button>`;}
function relatedGoals(st,id){return activeGoals(st).filter(g=>g.findings.includes(id)).map(g=>g.name).join(' · ');}
function findingRows(st,ids,showGoals=false){return ids.map(id=>{const f=findings[id],unread=isUnread(st,id);return `<button type="button" class="pt-goal pt-finding-row cursor-interaction" data-finding="${id}" data-unread="${unread}" aria-label="${f.title}. ${unread?f.change+', unread':'Reviewed'}. Open finding."><span><span class="pt-goal-heading"><span class="pt-goal-name">${f.title}</span><span class="${unread?'pt-finding-state':'pt-reviewed-count'}">${unread?f.change:'Reviewed'}</span></span><span class="pt-preview">${showGoals?relatedGoals(st,id):f.status}</span></span>${icon('chevron-right','pt-chevron')}</button>`;}).join('');}
function goalView(st){const g=goals.find(g=>g.id===st.selected)||goals[0];const ids=[...unreadFor(st,g),...g.findings.filter(id=>!isUnread(st,id))];const count=unreadFor(st,g).length;return `<section class="pt-card pt-detail">${backButton(st)}<div class="pt-detail-goal"><span class="pt-goal-icon">${goalIcon(g)}</span>Your Goal</div><h2>${g.name}</h2><div class="pt-detail-status">${count?`${count} unread ${count===1?'finding':'findings'}`:'All findings reviewed'}</div><div class="pt-finding-list">${findingRows(st,ids)}</div></section>`;}
function statusView(st){const g=goals.find(g=>g.id===st.selected)||goals.find(g=>g.status);return `<section class="pt-card pt-detail">${backButton(st)}<div class="pt-detail-goal"><span class="pt-goal-icon">${goalIcon(g)}</span>${g.name}</div><h2>${g.heading}</h2><div class="pt-detail-status">${g.status==='needs-input'?'Missing context':g.status==='no-pattern'?'Records reviewed':'Not enough context yet'}</div><p>${g.body}</p><p>${g.context}</p></section>`;}
function detail(st){const f=findings[st.finding]||findings.dairy;const g=goals.find(g=>g.id===st.selected&&g.findings.includes(st.finding))||activeGoals(st).find(g=>g.findings.includes(st.finding))||goals[0];return `<section class="pt-card pt-detail">${backButton(st)}<div class="pt-detail-goal"><span class="pt-goal-icon">${goalIcon(g)}</span>${g.name}</div><h2>${f.title}</h2><div class="pt-detail-status">${f.status}</div><p>${f.body}</p>${f.changed?`<section class="pt-change-summary"><h3>What changed</h3><p>${f.changed}</p></section>`:''}<details><summary>Explore the evidence</summary><p>${f.detail}</p></details><small>${f.foot}</small></section>`;}
function all(st){return `<section class="pt-card pt-detail">${backButton(st)}<h2 class="pt-all-heading">Your Goals</h2><div class="pt-finding-list">${rows(st)}</div></section>`;}
function unreadView(st){const ids=changedIds(st);return `<section class="pt-card pt-detail">${backButton(st)}<h2>Unread Insights</h2><div class="pt-detail-status">${ids.length?`${ids.length} ${ids.length===1?'finding':'findings'} to explore`:'All findings reviewed'}</div>${ids.length?`<div class="pt-finding-list">${findingRows(st,ids,true)}</div>`:'<p>Your reviewed findings remain available under Your Goals.</p><button type="button" class="pt-explore cursor-interaction" data-action="all">Explore Insights'+icon('arrow-right')+'</button>'}</section>`;}
function draw(phone,st){const top=phone.querySelector('.pt-content')?.scrollTop||0;const isToday=st.screen==='today';phone.dataset.screen=st.screen;phone.style.setProperty('--pt-text-scale',st.textScale);const content=st.screen==='today'?overview(st):st.screen==='all'?all(st):st.screen==='unread'?unreadView(st):st.screen==='goal'?goalView(st):st.screen==='status'?statusView(st):detail(st);phone.innerHTML=`<div class="pt-yarn" aria-hidden="true"></div><header class="pt-chrome"><div class="pt-status" aria-hidden="true"><span>9:41</span><span class="pt-island"></span><span class="pt-status-icons">${icon('signal')}${icon('wifi')}${icon('battery-full')}</span></div><div class="pt-toolbar">${isToday?`<img class="pt-logo" src="${logo}" alt="Plectara">`:'<span style="font-size:22px;font-weight:600">Insights</span>'}<span class="pt-pref" aria-label="Preferences">${native(62318)}</span></div></header><main class="pt-content">${st.care&&isToday?`<aside class="pt-card pt-care"><strong>${icon('circle-alert')}Consider Contacting a Clinician</strong><p>Some patterns are concerning enough to discuss with a clinician.</p></aside>`:''}${content}</main><div class="pt-capture" aria-hidden="true"><span class="pt-quick">${icon('zap')}Quick Log</span><span class="pt-log">${icon('plus')}Log</span></div><nav class="pt-nav" aria-label="App navigation"><div class="pt-nav-items">${[['Today',58986,'today'],['Timeline',61605,''],['Charts',61116,''],['Chat',62173,''],['Insights',58183,'all']].map(([label,code,action])=>`<${action?'button type="button"':'span'} class="pt-nav-item ${action?'cursor-interaction':''}" ${action?`data-nav="${action}"`:''} ${isToday&&label==='Today'||!isToday&&label==='Insights'?'aria-current="page"':''}><span class="pt-nav-icon">${native(code)}</span>${label}</${action?'button':'span'}>`).join('')}</div><div class="pt-home-indicator" aria-hidden="true"></div></nav>`;globalThis.lucide?.createIcons({attrs:{width:20,height:20}});phone.querySelector('.pt-content').scrollTop=st.keepScroll?top:0;st.keepScroll=false;}
function visit(st,screen,selected=st.selected,finding=st.finding){st.history.push({screen:st.screen,selected:st.selected,finding:st.finding});st.screen=screen;st.selected=selected;st.finding=finding;}
function openFinding(st,id){if(!findings[id])return;visit(st,'detail',st.selected,id);st.seen[id]=findings[id].revision;}
function restoreState(st,v){if(!v||typeof v!=='object')return;const {seen,screen,selected,finding,history,profile,care,textScale}=v;if(seen&&typeof seen==='object'&&!Array.isArray(seen))st.seen={...seen};if(screens.includes(screen))st.screen=screen;if(goals.some(g=>g.id===selected))st.selected=selected;if(findings[finding])st.finding=finding;if(Array.isArray(history))st.history=history.filter(x=>screens.includes(x.screen)).slice(-8);if(['Eight Selected Goals','Four Selected Goals'].includes(profile))st.profile=profile;if(typeof care==='boolean')st.care=care;if(typeof textScale==='number')st.textScale=Math.min(1.3,Math.max(1,textScale));}
root.querySelectorAll('.pt-phone').forEach(phone=>{const key=phone.dataset.case;const st={seen:key.startsWith('read')?Object.fromEntries(Object.entries(findings).map(([id,f])=>[id,f.revision])):{},screen:'today',selected:'symptoms',finding:'dairy',history:[],profile:'Eight Selected Goals',care:false,textScale:1};restoreState(st,saved[key]);states.set(key,st);draw(phone,st);phone.addEventListener('click',event=>{const goal=event.target.closest('[data-goal]');const finding=event.target.closest('[data-finding]');const action=event.target.closest('[data-action]')?.dataset.action;const nav=event.target.closest('[data-nav]')?.dataset.nav;if(goal){const g=goals.find(g=>g.id===goal.dataset.goal);if(!g)return;if(g.findings.length===1){visit(st,'detail',g.id,g.findings[0]);st.seen[g.findings[0]]=findings[g.findings[0]].revision;}else{visit(st,g.findings.length?'goal':'status',g.id);}}else if(finding){openFinding(st,finding.dataset.finding);}else if(nav){st.screen=nav;st.history=nav==='today'?[]:[{screen:'today',selected:st.selected,finding:st.finding}];}else if(action==='back'){const previous=st.history.pop();Object.assign(st,previous||{screen:'today'});}else if(action==='all'||action==='unread'){visit(st,action);}else{return;}draw(phone,st);persist();phone.querySelector(st.screen==='today'?'.pt-goal':'.pt-back')?.focus({preventScroll:true});});

});

})();

(async()=>{
 await document.fonts.ready;
 await Promise.all([...document.images].map(img=>img.decode().catch(()=>{})));
 const yarn=getComputedStyle(document.querySelector('.pt-yarn')).backgroundImage;
 const url=yarn.match(/^url\(["']?(.*?)["']?\)$/)?.[1];
 if(url){const image=new Image();image.src=url;await image.decode();}
 await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 document.documentElement.dataset.captureReady='true';
})();
